-- Formatos institucionales de consentimiento informado — versión 1.0 (BORRADOR).
-- El contenido jurídico debe ser revisado y aprobado por la institución antes de su uso oficial.
-- Mientras estén en borrador, la plataforma solo permite descargarlos con marca de agua
-- «BORRADOR — NO VÁLIDO» y no acepta consentimientos basados en ellos.
insert into ops.consentimiento_plantillas (servicio, version, titulo, secciones) values
('psicologia', '1.0', 'Consentimiento informado para teleatención psicológica', '[{"titulo": "1. Identificación de la persona atendida", "texto": "Nombre: {{servidor_nombre}}\nIdentificador institucional: {{servidor_codigo}}\nUnidad: {{servidor_unidad}}\nInstitución: Consejo de Gobierno del Régimen Especial de Galápagos (CGREG), Santa Cruz."}, {"titulo": "2. Descripción del servicio", "texto": "Atención psicológica clínica a distancia brindada por la Brigada de Atención Psicosocial y de Salud del CGREG a servidores afectados por el fenómeno de El Niño. Incluye entrevista, evaluación psicológica, intervención en crisis, primeros auxilios psicológicos, psicoterapia breve y seguimiento, según criterio profesional."}, {"titulo": "3. Objetivo de la atención", "texto": "Brindar acompañamiento y atención psicológica orientados a su bienestar emocional, identificar necesidades de apoyo y, cuando corresponda, coordinar derivaciones a otros servicios."}, {"titulo": "4. Modalidad telemática", "texto": "La atención se realiza a distancia mediante videollamada o llamada telefónica a través de los canales que la institución determine. La persona atendida debe procurar un espacio privado. La teleatención tiene limitaciones: no reemplaza la atención presencial cuando esta sea necesaria y no constituye un servicio de emergencias. Ante una emergencia debe llamar al ECU 911 o acudir al servicio de salud más cercano. Si la comunicación se interrumpe, el profesional intentará restablecerla por el canal de contacto registrado."}, {"titulo": "5. Confidencialidad", "texto": "La información compartida es confidencial y se registra en una historia clínica electrónica con acceso restringido al personal clínico que participa en su atención, según su función. Coordinación General accede únicamente a información administrativa y operativa. La confidencialidad puede limitarse solo en los casos previstos por la ley, por ejemplo ante un riesgo grave e inminente para la vida o integridad de la persona o de terceros. Las sesiones no se graban."}, {"titulo": "6. Protección de datos personales", "texto": "El CGREG trata sus datos personales, incluidos datos relativos a la salud, conforme a la Ley Orgánica de Protección de Datos Personales del Ecuador, con la finalidad exclusiva de brindarle atención y dar seguimiento a la intervención. Los datos se almacenan cifrados, con control de acceso por roles y registro de auditoría, y se conservan durante los plazos que establezca la normativa aplicable a historias clínicas."}, {"titulo": "7. Derechos de la persona atendida", "texto": "Usted tiene derecho a recibir información clara sobre la atención; a aceptar o rechazar la atención sin que ello afecte su relación laboral; a retirar este consentimiento en cualquier momento, sin efecto retroactivo sobre la atención ya brindada; y a ejercer los derechos reconocidos en la Ley Orgánica de Protección de Datos Personales (entre ellos acceso, rectificación y actualización, eliminación, oposición, portabilidad y suspensión del tratamiento), con las limitaciones que establezca la normativa sobre conservación de historias clínicas."}, {"titulo": "Autorización", "texto": "Declaro que he leído y comprendido este documento, que he podido formular preguntas y que estas fueron respondidas. De manera libre y voluntaria autorizo recibir el servicio descrito en modalidad telemática y el tratamiento de mis datos personales para esta finalidad."}, {"titulo": "Profesional responsable", "texto": "Nombre: {{profesional_nombre}}\nCargo / especialidad: {{profesional_titulo}}"}, {"titulo": "Fecha y firma", "texto": "Fecha: {{fecha}}\n\nFirma de la persona atendida: ______________________________\n\nFirma del profesional: ______________________________"}]'::jsonb),
('telemedicina', '1.0', 'Consentimiento informado para telemedicina', '[{"titulo": "1. Identificación de la persona atendida", "texto": "Nombre: {{servidor_nombre}}\nIdentificador institucional: {{servidor_codigo}}\nUnidad: {{servidor_unidad}}\nInstitución: Consejo de Gobierno del Régimen Especial de Galápagos (CGREG), Santa Cruz."}, {"titulo": "2. Descripción del servicio", "texto": "Consulta médica a distancia brindada por la Brigada de Atención Psicosocial y de Salud del CGREG. Incluye anamnesis, orientación médica, indicaciones y seguimiento, con duración aproximada de 20 a 30 minutos. El examen físico es limitado en esta modalidad."}, {"titulo": "3. Objetivo de la atención", "texto": "Valorar su estado de salud, orientar sobre medidas de cuidado y, cuando sea necesario, indicar atención presencial o coordinar derivaciones."}, {"titulo": "4. Modalidad telemática", "texto": "La atención se realiza a distancia mediante videollamada o llamada telefónica a través de los canales que la institución determine. La persona atendida debe procurar un espacio privado. La teleatención tiene limitaciones: no reemplaza la atención presencial cuando esta sea necesaria y no constituye un servicio de emergencias. Ante una emergencia debe llamar al ECU 911 o acudir al servicio de salud más cercano. Si la comunicación se interrumpe, el profesional intentará restablecerla por el canal de contacto registrado."}, {"titulo": "5. Confidencialidad", "texto": "La información compartida es confidencial y se registra en una historia clínica electrónica con acceso restringido al personal clínico que participa en su atención, según su función. Coordinación General accede únicamente a información administrativa y operativa. La confidencialidad puede limitarse solo en los casos previstos por la ley, por ejemplo ante un riesgo grave e inminente para la vida o integridad de la persona o de terceros. Las sesiones no se graban."}, {"titulo": "6. Protección de datos personales", "texto": "El CGREG trata sus datos personales, incluidos datos relativos a la salud, conforme a la Ley Orgánica de Protección de Datos Personales del Ecuador, con la finalidad exclusiva de brindarle atención y dar seguimiento a la intervención. Los datos se almacenan cifrados, con control de acceso por roles y registro de auditoría, y se conservan durante los plazos que establezca la normativa aplicable a historias clínicas."}, {"titulo": "7. Derechos de la persona atendida", "texto": "Usted tiene derecho a recibir información clara sobre la atención; a aceptar o rechazar la atención sin que ello afecte su relación laboral; a retirar este consentimiento en cualquier momento, sin efecto retroactivo sobre la atención ya brindada; y a ejercer los derechos reconocidos en la Ley Orgánica de Protección de Datos Personales (entre ellos acceso, rectificación y actualización, eliminación, oposición, portabilidad y suspensión del tratamiento), con las limitaciones que establezca la normativa sobre conservación de historias clínicas."}, {"titulo": "Autorización", "texto": "Declaro que he leído y comprendido este documento, que he podido formular preguntas y que estas fueron respondidas. De manera libre y voluntaria autorizo recibir el servicio descrito en modalidad telemática y el tratamiento de mis datos personales para esta finalidad."}, {"titulo": "Profesional responsable", "texto": "Nombre: {{profesional_nombre}}\nCargo / especialidad: {{profesional_titulo}}"}, {"titulo": "Fecha y firma", "texto": "Fecha: {{fecha}}\n\nFirma de la persona atendida: ______________________________\n\nFirma del profesional: ______________________________"}]'::jsonb),
('psiquiatria', '1.0', 'Consentimiento informado para valoración psiquiátrica por teleatención', '[{"titulo": "1. Identificación de la persona atendida", "texto": "Nombre: {{servidor_nombre}}\nIdentificador institucional: {{servidor_codigo}}\nUnidad: {{servidor_unidad}}\nInstitución: Consejo de Gobierno del Régimen Especial de Galápagos (CGREG), Santa Cruz."}, {"titulo": "2. Descripción del servicio", "texto": "Valoración psiquiátrica a distancia realizada por médico especialista en Psiquiatría, a la que se accede mediante derivación de un profesional de la brigada. Incluye entrevista clínica, evaluación especializada, orientación y recomendaciones de seguimiento."}, {"titulo": "3. Objetivo de la atención", "texto": "Realizar una valoración especializada del caso derivado, emitir recomendaciones y orientar el seguimiento."}, {"titulo": "4. Modalidad telemática", "texto": "La atención se realiza a distancia mediante videollamada o llamada telefónica a través de los canales que la institución determine. La persona atendida debe procurar un espacio privado. La teleatención tiene limitaciones: no reemplaza la atención presencial cuando esta sea necesaria y no constituye un servicio de emergencias. Ante una emergencia debe llamar al ECU 911 o acudir al servicio de salud más cercano. Si la comunicación se interrumpe, el profesional intentará restablecerla por el canal de contacto registrado."}, {"titulo": "5. Confidencialidad", "texto": "La información compartida es confidencial y se registra en una historia clínica electrónica con acceso restringido al personal clínico que participa en su atención, según su función. Coordinación General accede únicamente a información administrativa y operativa. La confidencialidad puede limitarse solo en los casos previstos por la ley, por ejemplo ante un riesgo grave e inminente para la vida o integridad de la persona o de terceros. Las sesiones no se graban."}, {"titulo": "6. Protección de datos personales", "texto": "El CGREG trata sus datos personales, incluidos datos relativos a la salud, conforme a la Ley Orgánica de Protección de Datos Personales del Ecuador, con la finalidad exclusiva de brindarle atención y dar seguimiento a la intervención. Los datos se almacenan cifrados, con control de acceso por roles y registro de auditoría, y se conservan durante los plazos que establezca la normativa aplicable a historias clínicas."}, {"titulo": "7. Derechos de la persona atendida", "texto": "Usted tiene derecho a recibir información clara sobre la atención; a aceptar o rechazar la atención sin que ello afecte su relación laboral; a retirar este consentimiento en cualquier momento, sin efecto retroactivo sobre la atención ya brindada; y a ejercer los derechos reconocidos en la Ley Orgánica de Protección de Datos Personales (entre ellos acceso, rectificación y actualización, eliminación, oposición, portabilidad y suspensión del tratamiento), con las limitaciones que establezca la normativa sobre conservación de historias clínicas."}, {"titulo": "8. Derivación", "texto": "Autorizo que el profesional que realizó la derivación y el especialista compartan la información clínica estrictamente necesaria para la valoración y el seguimiento."}, {"titulo": "Autorización", "texto": "Declaro que he leído y comprendido este documento, que he podido formular preguntas y que estas fueron respondidas. De manera libre y voluntaria autorizo recibir el servicio descrito en modalidad telemática y el tratamiento de mis datos personales para esta finalidad."}, {"titulo": "Profesional responsable", "texto": "Nombre: {{profesional_nombre}}\nCargo / especialidad: {{profesional_titulo}}"}, {"titulo": "Fecha y firma", "texto": "Fecha: {{fecha}}\n\nFirma de la persona atendida: ______________________________\n\nFirma del profesional: ______________________________"}]'::jsonb);
